import{_ as n,c as t,o,aj as s}from"./chunks/framework.B-qp3evu.js";const _=JSON.parse('{"title":"MCK Meeting Series","description":"","frontmatter":{"title":"MCK Meeting Series","date":"2026-11-17","banner":"assets/events/20261117_mck_neonephos_series_banner.svg","bannerMobile":"assets/events/20261117_mck_neonephos_series_banner_mobile.svg","bannerSmall":"assets/events/20261117_mck_neonephos_series_banner_small.svg","backgroundhex":"#128256ff","tags":["neonephos","mck","ipcei"],"published":true,"sidebar":false,"aside":false,"prev":false,"next":false,"layout":"EventEntryThemeComponent"},"headers":[],"relativePath":"events/2026_11_17_MCK_NeoNephos_Series.md","filePath":"events/2026_11_17_MCK_NeoNephos_Series.md"}'),a={name:"events/2026_11_17_MCK_NeoNephos_Series.md"};function i(r,e,l,p,c,d){return o(),t("div",null,e[0]||(e[0]=[s('<h1 id="neonephos-meeting-series" tabindex="-1">NeoNephos Meeting Series <a class="header-anchor" href="#neonephos-meeting-series" aria-label="Permalink to &quot;NeoNephos Meeting Series&quot;">​</a></h1><p>The next IPCEI-CIS Workstream 2 Multi Cluster Kubernetes (MCK) meeting session will be held on the <strong>17th of November from 10:00-11:30 am CET</strong>.</p><p><strong>Agenda:</strong><strong>Slot 1</strong>: Autonomous Operations: Enabling Data Centers to Run Themselves (Jan Rumig, SAP + Florian Müller, SAP) Autonomous Operations is an initiative to enable data centers to manage themselves - reducing manual effort through intelligent, end-to-end automation. This presentation provides an overview of the project, its core concepts, and its key architectural components. It also explores how the Operational Context Graph - a building block of Autonomous Operations - extends beyond autonomous operations into domains such as sustainability, serving as a versatile foundation for cross-domain intelligence.</p><p><strong>Slot 2</strong>: DTcargo: Shipping Cloud-Native Applications to Mars and Beyond (Tobias Nöthlich, D3TN) With the European Space Agency investing substantial efforts in the research and development of the Solar System Internet (SSI), the idea of running cloud-native applications on Mars is no longer limited to Sci-Fi movies. However, deploying software across millions of kilometers (where single trip latencies routinely exceed 10 minutes and connections are frequently interrupted) introduces unique challenges, that standard deployment tooling cannot handle. In this talk, we introduce DTcargo, a tool designed for bridging this gap. We will explore how DTcargo combines Delay- and Disruption Tolerant Networking (DTN), one of the technical foundations of the SSI, with the Open Component Model (OCM) to create a secure, resilient and user-friendly pipeline for shipping applications into deep space.</p><hr><p>👉 Join the meeting <a href="https://teams.microsoft.com/l/meetup-join/19%3ameeting_NzQ0ZmE4OWYtNjgyYi00ZGYyLWE5NjMtY2M5NzhkNzU2MjJh%40thread.v2/0?context=%7b%22Tid%22%3a%2242f7676c-f455-423c-82f6-dc2d99791af7%22%2c%22Oid%22%3a%2268b1645a-7771-4b42-a2ef-854bf9dcfa76%22%7d" target="_blank" rel="noreferrer">here</a></p>',6)]))}const m=n(a,[["render",i]]);export{_ as __pageData,m as default};
